socket.on('message', (data) => {
  if (typeof data !== 'string') {
    return;
  }

  const message = data.trim();

  if (!message || message.length > 1000) {
    return;
  }

  io.emit('message', {
    id: crypto.randomUUID(),
    text: message,
    createdAt: new Date().toISOString(),
  });
});

